"""V51 bootstrap. Generates editable build_electric_v51_source.py and transparent sprite frames in CI."""
from pathlib import Path
import zlib,base64
src=zlib.decompress(base64.b64decode('')).decode('utf-8')
p=Path(__file__).with_name('build_electric_v51_source.py')
p.write_text(src,encoding='utf-8')
exec(compile(src,str(p),'exec'),{'__file__':str(p),'__name__':'__main__'})
